css:
.roadmap-sim-container {
    padding: 20px;
    background: linear-gradient(165deg, #0b1c2c 0%, #102a3f 55%, #14344d 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e6edf3;
}

/* ---- Header ---- */
.roadmap-sim-header {
    background: linear-gradient(135deg, #0a2f4a 0%, #14506e 50%, #0b1c2c 100%);
    color: #ffffff;
    padding: 32px 30px;
    border-radius: 16px;
    margin-bottom: 22px;
    box-shadow: 0 12px 30px rgba(0,0,0,0.45);
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.08);
}

.roadmap-sim-header::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(45,212,191,0.10) 0%, transparent 60%);
    pointer-events: none;
}

.roadmap-sim-header-icon {
    font-size: 2.6rem;
    margin-bottom: 8px;
}

.roadmap-sim-header h1 {
    font-size: 1.9rem;
    font-weight: 800;
    margin-bottom: 6px;
    letter-spacing: 0.3px;
}

.roadmap-sim-header p {
    font-size: 1rem;
    opacity: 0.88;
    margin: 0 0 14px 0;
}

.roadmap-sim-clock {
    display: inline-block;
    background: rgba(0,0,0,0.35);
    border: 1px solid rgba(255,255,255,0.18);
    border-radius: 999px;
    padding: 6px 18px;
    font-size: 0.92rem;
    font-weight: 600;
    letter-spacing: 0.4px;
}

.roadmap-sim-clock #runwayClockDisplay {
    color: #f5b942;
    font-weight: 800;
    margin: 0 4px;
}

/* ---- Period counter ---- */
.roadmap-sim-period-counter {
    text-align: center;
    font-size: 1.05rem;
    color: #aebfcf;
    margin-bottom: 22px;
    font-weight: 600;
}

.roadmap-sim-period-counter span {
    margin: 0 3px;
}

.roadmap-sim-period-counter #currentDay,
.roadmap-sim-period-counter #maxPeriods {
    color: #2dd4bf;
    font-weight: 800;
}

.roadmap-sim-round-name {
    display: inline-block;
    margin-left: 10px;
    padding: 3px 14px;
    background: rgba(45,212,191,0.16);
    border: 1px solid rgba(45,212,191,0.45);
    border-radius: 999px;
    color: #7fe6d8;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

/* ---- KPI cards ---- */
.roadmap-sim-kpi-section {
    margin-bottom: 22px;
}

.roadmap-sim-kpi-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 16px;
}

.roadmap-sim-kpi-cards-secondary {
    grid-template-columns: repeat(3, 1fr);
    margin-bottom: 0;
}

.roadmap-sim-kpi-card {
    background: linear-gradient(160deg, #143247 0%, #102a3f 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 18px 18px 20px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.roadmap-sim-kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 26px rgba(0,0,0,0.45);
}

.roadmap-kpi-hero {
    border: 1px solid rgba(45,212,191,0.40);
    background: linear-gradient(160deg, #0f3a3a 0%, #102a3f 100%);
}

.roadmap-sim-kpi-label {
    font-size: 0.82rem;
    color: #93a7ba;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px;
    font-weight: 600;
}

.roadmap-sim-kpi-value {
    font-size: 2.6rem;
    font-weight: 800;
    color: #ffffff;
    line-height: 1.05;
}

.roadmap-kpi-hero .roadmap-sim-kpi-value {
    color: #2dd4bf;
}

.roadmap-kpi-small .roadmap-sim-kpi-value {
    font-size: 1.5rem;
}

.roadmap-sim-kpi-sub {
    font-size: 0.74rem;
    color: #7488a0;
    margin-top: 8px;
    line-height: 1.3;
}

.roadmap-sim-kpi-bar-bg {
    height: 8px;
    background: rgba(255,255,255,0.10);
    border-radius: 6px;
    margin-top: 12px;
    overflow: hidden;
}

.roadmap-sim-kpi-bar-fill {
    height: 100%;
    border-radius: 6px;
    transition: width 0.5s ease;
}

.roadmap-arr-fill { background: linear-gradient(90deg, #14b8a6, #2dd4bf); }
.roadmap-nrr-fill { background: linear-gradient(90deg, #3b82f6, #60a5fa); }
.roadmap-runway-fill { background: linear-gradient(90deg, #f59e0b, #f5b942); }
.roadmap-focus-fill { background: linear-gradient(90deg, #8b5cf6, #a78bfa); }

/* ---- Briefing ---- */
.roadmap-sim-briefing {
    background: linear-gradient(160deg, #143247 0%, #102a3f 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-left: 4px solid #2dd4bf;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.roadmap-sim-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #f5b942;
}

.roadmap-sim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.65;
    color: #ccd8e3;
}

.roadmap-sim-briefing-text strong {
    color: #ffffff;
}

.roadmap-sim-briefing-text em {
    color: #7fe6d8;
    font-style: italic;
}

.roadmap-sim-event-alert {
    margin-top: 16px;
    padding: 14px 16px;
    background: rgba(245,158,11,0.14);
    border: 1px solid rgba(245,158,11,0.45);
    border-radius: 10px;
    color: #ffe2b0;
    font-size: 0.92rem;
    line-height: 1.55;
}

/* ---- Controls ---- */
.roadmap-sim-controls {
    background: linear-gradient(160deg, #143247 0%, #102a3f 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.roadmap-sim-controls h3 {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: #ffffff;
}

.roadmap-sim-decisions-note {
    font-size: 0.86rem;
    color: #93a7ba;
    margin-bottom: 18px;
    font-style: italic;
}

.roadmap-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px 22px;
}

.roadmap-sim-input-group {
    display: flex;
    flex-direction: column;
    margin-bottom: 4px;
}

.roadmap-input-wide {
    margin-bottom: 20px;
}

.roadmap-sim-input-group label {
    font-size: 0.9rem;
    font-weight: 600;
    color: #c4d2df;
    margin-bottom: 7px;
}

.roadmap-sim-container .form-control {
    background-color: #0c2233;
    color: #eef4fa;
    border: 1px solid rgba(255,255,255,0.16);
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
}

.roadmap-sim-container .form-control:focus {
    border-color: #2dd4bf;
    box-shadow: 0 0 0 3px rgba(45,212,191,0.18);
    background-color: #0c2233;
    color: #eef4fa;
    outline: none;
}

.roadmap-sim-container select.form-control {
    background-color: #0c2233;
    color: #eef4fa;
}

.roadmap-sim-container select.form-control option {
    background-color: #0c2233;
    color: #eef4fa;
}

.roadmap-sim-hint {
    font-size: 0.76rem;
    color: #7488a0;
    margin-top: 6px;
    line-height: 1.35;
}

/* ---- Focus allocation block ---- */
.roadmap-sim-focus-block {
    background: rgba(139,92,246,0.08);
    border: 1px solid rgba(139,92,246,0.35);
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 20px;
}

.roadmap-sim-focus-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    font-size: 0.95rem;
    font-weight: 700;
    color: #c8b6f5;
    margin-bottom: 6px;
}

.roadmap-sim-focus-tally {
    font-size: 0.85rem;
    font-weight: 600;
    color: #aebfcf;
}

.roadmap-sim-focus-tally #focusAllocated,
.roadmap-sim-focus-tally #focusRemaining {
    color: #ffffff;
    font-weight: 800;
}

.roadmap-sim-focus-tally.roadmap-over #focusAllocated,
.roadmap-sim-focus-tally.roadmap-over #focusRemaining {
    color: #ff7a85;
}

.roadmap-sim-focus-tally.roadmap-ok #focusAllocated,
.roadmap-sim-focus-tally.roadmap-ok #focusRemaining {
    color: #2dd4bf;
}

.roadmap-sim-container .form-control.roadmap-alloc {
    background-color: #1a1430;
    border-color: rgba(139,92,246,0.4);
}

/* ---- Buttons ---- */
.roadmap-sim-btn-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 22px;
    flex-wrap: wrap;
}

.roadmap-sim-container .btn-primary {
    background: linear-gradient(135deg, #0d9488 0%, #2dd4bf 100%);
    border: none;
    color: #06231f;
    font-weight: 800;
    letter-spacing: 0.4px;
    padding: 12px 30px;
    border-radius: 10px;
    box-shadow: 0 6px 16px rgba(13,148,136,0.4);
}

.roadmap-sim-container .btn-primary:hover {
    background: linear-gradient(135deg, #14b8a6 0%, #5eead4 100%);
    color: #06231f;
}

.roadmap-sim-container .btn-outline-secondary {
    color: #aebfcf;
    border-color: rgba(255,255,255,0.25);
    border-radius: 10px;
}

.roadmap-sim-container .btn-outline-secondary:hover {
    background: rgba(255,255,255,0.08);
    color: #ffffff;
}

/* ---- Charts ---- */
.roadmap-sim-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.roadmap-sim-chart-box {
    background: #f5f8fb;
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
    min-height: 320px;
}

/* ---- History ---- */
.roadmap-sim-history {
    background: linear-gradient(160deg, #143247 0%, #102a3f 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 22px 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.roadmap-sim-history h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #ffffff;
}

.roadmap-sim-history table {
    color: #ccd8e3;
    margin-bottom: 0;
}

.roadmap-sim-history .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(255,255,255,0.04);
}

.roadmap-sim-history th {
    color: #93a7ba;
    border-color: rgba(255,255,255,0.12);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.roadmap-sim-history td {
    border-color: rgba(255,255,255,0.08);
    font-size: 0.88rem;
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
    .roadmap-sim-container {
        padding: 12px;
    }
    .roadmap-sim-header h1 {
        font-size: 1.45rem;
    }
    .roadmap-sim-kpi-cards,
    .roadmap-sim-kpi-cards-secondary {
        grid-template-columns: 1fr;
    }
    .roadmap-sim-input-grid {
        grid-template-columns: 1fr;
    }
    .roadmap-sim-charts {
        grid-template-columns: 1fr;
    }
    .roadmap-sim-kpi-value {
        font-size: 2.1rem;
    }
    .roadmap-sim-focus-header {
        flex-direction: column;
        align-items: flex-start;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.sr-completion { padding: 8px 4px 4px; }
.sr-cm-head { text-align: center; margin-bottom: 16px; }
.sr-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6df6; }
.sr-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #64748b; }
.sr-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; }
.sr-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.sr-cm-yes { background: rgba(34,197,94,0.14); color: #16a34a; border: 1px solid rgba(34,197,94,0.4); }
.sr-cm-no { background: rgba(239,68,68,0.12); color: #dc2626; border: 1px solid rgba(239,68,68,0.4); }
.sr-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.sr-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(47,109,246,0.06); border: 1px solid rgba(47,109,246,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.sr-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2f6df6; }
.sr-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #64748b; text-transform: uppercase; letter-spacing: 0.03em; }
.sr-cm-insights-title { font-weight: 700; margin: 8px 0 6px; }
.sr-cm-insights { margin: 0; padding-left: 20px; }
.sr-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; }

