                var aiClear = ds.aiResolved || ds.aiChurnTaken; // at least no longer ambiguous

                var passes = 0;
                if (arrPath) passes++;
                if (nrrOk) passes++;
                if (runwayOk) passes++;
                if (focusedStory) passes++;
                if (aiClear) passes++;

                ds.verdict = passes >= 4 ? 'funded' : 'rejected';
            } else {
                ds.verdict = 'unfolding';
            }

            // ---- History ----
            ds.arrHistory.push(ds.arr);
            ds.nrrHistory.push(ds.nrr);
            ds.runwayHistory.push(ds.runway);

            this._updateBars(ds);

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            var res = {
                period: period,
                core: d.core,
                focusRetention: d.focusRetention,
                focusEnterprise: d.focusEnterprise,
                focusVerticals: d.focusVerticals,
                focusAI: d.focusAI,
                focusReserve: d.focusReserve,
                aiDecision: d.aiDecision,
                aiNote: aiNote,
                sequence: d.sequence,
                fundedBets: fundedBets,
                arr: ds.arr,
                nrr: ds.nrr,
                growth: ds.growth,
                burn: ds.burn,
                cash: ds.cash,
                runway: ds.runway,
                focusScore: ds.focusScore,
                verdict: ds.verdict
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); period 4 locks the authoritative score.
            ds.performance = { overallScore: this._composite(res, (state.history || []).concat([{ results: res }])) };
            return res;
        }

        _updateBars(ds) {
            var arrBar = document.getElementById('arrBar');
            var nrrBar = document.getElementById('nrrBar');
            var runwayBar = document.getElementById('runwayBar');
            var focusBar = document.getElementById('focusBar');
            if (arrBar) arrBar.style.width = Math.max(0, Math.min(100, (ds.arr / this.TARGET_ARR) * 100)) + '%';
            // NRR bar: map 80..140 onto 0..100
            if (nrrBar) nrrBar.style.width = Math.max(0, Math.min(100, (ds.nrr - 80) / 60 * 100)) + '%';
            // Runway bar: 24 months = full
            if (runwayBar) runwayBar.style.width = Math.max(0, Math.min(100, (ds.runway / 24) * 100)) + '%';
            if (focusBar) focusBar.style.width = Math.max(0, Math.min(100, ds.focusScore)) + '%';
        }

        // EQIL 2026-08-20 i18n fix. Resolve the live language from vcI18n, which is
        // the only source of truth in production. The USF SimulationFramework
        // exposes no language, lang or currentLanguage property; testing/usf_shim.js
        // does, which is why earlier offline runs read it and appeared to pass.
        _lang() {
            var norm = function (v) { return String(v).split('-')[0].toLowerCase(); };
            try {
                if (window.vcI18n && window.vcI18n._lang) return norm(window.vcI18n._lang);
                var s = window.mySimulation;
                if (s && s.language) return norm(s.language);
                if (s && s.currentLanguage) return norm(s.currentLanguage);
                if (document.documentElement && document.documentElement.lang) {
                    return norm(document.documentElement.lang);
                }
            } catch (e) {}
            return 'en';
        }

        // EQIL 2026-08-20 i18n fix. applyTranslations only rewrites data-i18n nodes.
        // The briefing body, round name, clock and event alert are written by this
        // adapter, so a mid-session language switch must re-run the render.
        _bindLangRepaint() {
            if (this._langRepaintBound) return;
            this._langRepaintBound = true;
            var self = this;
            var repaint = function () {
                try {
                    var s = window.mySimulation;
                    var st = (s && s.state) ? s.state : { currentPeriod: 1 };
                    self._updateBriefing(st);
                    if (self._lastCoachKey && s && typeof s.t === 'function') {
                        var c = document.getElementById('coachText');
                        if (c) c.innerHTML = s.t(self._lastCoachKey);
                    }
                } catch (e) {}
            };
            try { document.addEventListener('express:langchanged', repaint); } catch (e) {}
            try {
                var s0 = window.mySimulation;
                if (s0 && s0.eventBus && typeof s0.eventBus.on === 'function') {
                    s0.eventBus.on('language:changed', repaint);
                }
            } catch (e) {}
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = this._lang();

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefingEn;
            }

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) {
                nameEl.textContent = lang === 'es' ? round.nameEs : round.nameEn;
            }

            var noteEl = document.getElementById('liveLeversNote');
            if (noteEl) {
                var noteKey = 'levers_note_r' + (idx + 1);
                try { noteEl.textContent = window.mySimulation.t(noteKey); } catch (e) {}
            }

            var eventEl = document.getElementById('eventAlert');
            if (eventEl) {
                var eventText = lang === 'es' ? round.eventEs : round.eventEn;
                if (eventText) {
                    eventEl.innerHTML = eventText;
                    eventEl.style.display = 'block';
                } else {
                    eventEl.style.display = 'none';
                }
            }

            this._updateFocusTally();
        }

        // Live focus tally readout under the allocation block.
        _updateFocusTally() {
            var ids = ['focusRetentionInput', 'focusEnterpriseInput', 'focusVerticalsInput', 'focusAIInput', 'focusReserveInput'];
            var total = 0, ok = true;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                var v = el ? parseInt(el.value, 10) : 0;
                if (!Number.isFinite(v)) { v = 0; ok = false; }
                total += v;
            });
            var allocEl = document.getElementById('focusAllocated');
            var remEl = document.getElementById('focusRemaining');
            if (allocEl) allocEl.textContent = total;
            if (remEl) remEl.textContent = (100 - total);
            var tally = document.querySelector('.roadmap-sim-focus-tally');
            if (tally) {
                tally.classList.remove('roadmap-over', 'roadmap-ok');
                if (total === 100) tally.classList.add('roadmap-ok');
                else if (total > 100) tally.classList.add('roadmap-over');
            }
        }

