        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the final debrief.
        // Weights & penalties identical to v1.0.0.
        _composite(r, history) {
            var arr = r.arr || 0, nrr = r.nrr || 0, runway = r.runway || 0, focusScore = r.focusScore || 0;
            var verdict = r.verdict || 'rejected';
            var arrScore = Math.min(100, (arr / this.TARGET_ARR) * 100) * 0.30;
            var nrrScore = Math.max(0, Math.min(100, (nrr - 90) / 30 * 100)) * 0.25;
            var runwayScore = Math.max(0, Math.min(100, (runway / 18) * 100)) * 0.20;
            var focusScoreW = focusScore * 0.15;
            var resolvedClean = (history || []).some(function(h) { return h.results && (h.results.aiNote === 'park_churn'); }) ? 0 : 1;
            var aiScore = (resolvedClean ? 100 : 40) * 0.10;
            var totalScore = Math.round(arrScore + nrrScore + runwayScore + focusScoreW + aiScore);
            if (runway < 12) totalScore = Math.max(0, totalScore - 15);
            else if (runway < this.MIN_RUNWAY) totalScore = Math.max(0, totalScore - 7);
            var bonus = verdict === 'funded' ? 1.1 : 1.0;
            return Math.min(100, Math.round(totalScore * bonus));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var arr = r.arr || 0;
            var nrr = r.nrr || 0;
            var runway = r.runway || 0;
            var focusScore = r.focusScore || 0;
            var verdict = r.verdict || 'rejected';

            var totalScore = this._composite(r, history);

            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            var performanceKey = 'grade_trap';
            if (totalScore >= 80 && verdict === 'funded') performanceKey = 'grade_focused';
            else if (totalScore >= 64) performanceKey = 'grade_operator';
            else if (totalScore >= 46) performanceKey = 'grade_improving';
            var performance = T(performanceKey);

            var insights = [];

            var everChasedAll = history.some(function(h) { return h.results && h.results.fundedBets >= 3; });
            if (everChasedAll) insights.push(T('ins_chased_all'));

            var ledWithAI = history.some(function(h) { return h.results && h.results.core === 'ai'; });
            var ledWithEverything = history.some(function(h) { return h.results && h.results.core === 'everything'; });
            if (ledWithEverything) insights.push(T('ins_core_everything'));
            else if (ledWithAI) insights.push(T('ins_core_ai'));

            var parked = history.some(function(h) { return h.results && h.results.aiNote === 'park_churn'; });
            if (parked) insights.push(T('ins_parked'));

            var frontloaded = history.some(function(h) { return h.results && h.results.sequence === 'frontload' && h.results.nrr < 100; });
            if (frontloaded) insights.push(T('ins_frontload'));

            if (nrr >= 100) insights.push(T('ins_nrr_ok'));
            else insights.push(T('ins_nrr_low'));

            if (runway >= this.MIN_RUNWAY) insights.push(T('ins_runway_ok', { m: Math.round(runway) }));
            else insights.push(T('ins_runway_low', { m: Math.round(runway) }));

            if (verdict === 'funded') insights.push(T('ins_verdict_funded'));
            else insights.push(T('ins_verdict_rejected'));

            return {
                totalScore: totalScore,
                arr: arr,
                nrr: nrr,
                runway: runway,
                focusScore: focusScore,
                verdict: verdict,
                overallScore: totalScore,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore : 0;
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var funded = s.verdict === 'funded';
            var badge = funded
                ? '<span class="sr-cm-badge sr-cm-yes">' + T('cm_funded') + '</span>'
                : '<span class="sr-cm-badge sr-cm-no">' + T('cm_rejected') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="sr-cm-metric"><span class="sr-cm-mv">\u00a3' + (Math.round((s.arr||0)*10)/10) + 'm</span><span class="sr-cm-ml">' + T('cm_m_arr') + '</span></div>'
                + '<div class="sr-cm-metric"><span class="sr-cm-mv">' + Math.round(s.nrr||0) + '%</span><span class="sr-cm-ml">' + T('cm_m_nrr') + '</span></div>'
                + '<div class="sr-cm-metric"><span class="sr-cm-mv">' + Math.round(s.runway||0) + '</span><span class="sr-cm-ml">' + T('cm_m_runway') + '</span></div>'
                + '<div class="sr-cm-metric"><span class="sr-cm-mv">' + Math.round(s.focusScore||0) + '</span><span class="sr-cm-ml">' + T('cm_m_focus') + '</span></div>';
            return ''
                + '<div class="sr-completion">'
                +   '<div class="sr-cm-head">'
                +     '<div class="sr-cm-score">' + score + '<span class="sr-cm-score-max">/100</span></div>'
                +     '<div class="sr-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="sr-cm-metrics">' + metrics + '</div>'
                +   '<div class="sr-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="sr-cm-insights">' + items + '</ul>'
                + '</div>';
        }

